#include <iostream>
#include <vector>

void printVector(const std::string& name, const std::vector<int>& vec) {
    std::cout << name << " (size " << vec.size() << "): ";
    for (int val : vec) {
        std::cout << val << " ";
    }
    std::cout << "\n";
}

int main() {
    // 1. Value-initialization with specified size
    std::vector<int> v1(4);
    std::vector<int> v2(3);

    // Populate elements
    for (size_t i = 0; i < v1.size(); ++i) {
        v1[i] = static_cast<int>((i + 1) * 10);
    }
    for (size_t i = 0; i < v2.size(); ++i) {
        v2[i] = static_cast<int>((i + 1) * 5);
    }

    printVector("v1", v1);
    printVector("v2", v2);

    std::cout << "v1 != v2: " << std::boolalpha << (v1 != v2) << "\n";

    // 2. Copy construction
    std::vector<int> v3(v1);
    printVector("v3 (copy of v1)", v3);
    std::cout << "v1 == v3: " << (v1 == v3) << "\n";

    // 3. Assignment operator
    v1 = v2;
    printVector("v1 after v1 = v2", v1);
    std::cout << "v1 == v2: " << (v1 == v2) << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <stdexcept>

int main() {
    std::vector<int> data = {10, 20, 30};

    // 1. Modifying elements using [] as an lvalue
    data[1] = 99;
    std::cout << "data[1] after modification: " << data[1] << "\n";

    // 2. Demonstrating push_back to dynamically grow
    std::cout << "Size before push_back: " << data.size() << "\n";
    data.push_back(1000);
    std::cout << "Size after push_back: " << data.size() << "\n";

    std::cout << "Vector elements: ";
    for (int x : data) {
        std::cout << x << " ";
    }
    std::cout << "\n";

    // 3. Bounds checking with at() and try-catch
    try {
        std::cout << "Attempting to access index 10 via at():\n";
        std::cout << data.at(10) << "\n"; // Out of bounds!
    }
    catch (const std::out_of_range&) {
        std::cout << "Caught out_of_range exception successfully.\n";
    }

    std::cout << "Program continues normally after catch block.\n";
    return 0;
}
